com.mirth.connect.plugins.javascriptstep.script:
var __li = channelMap.get('interactionId');
logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __li + " ]: STEP lookup_manager - START. requestedPath=" + channelMap.get('requestedPath'));
logger.info("HTTP request validation started.");

/********************************************
    1 FETCH JDBC SECRET (JSON secret)
********************************************/

try {

	var username = LookupHelper.get("Config-sensitive", "MC_JDBC_USERNAME");
	var password = LookupHelper.get("Config-sensitive", "MC_JDBC_PASSWORD");

	channelMap.put("JDBC_USERNAME", username);
	channelMap.put("JDBC_PASSWORD", password);
     globalMap.put("JDBC_USERNAME", username);
     globalMap.put("JDBC_PASSWORD", password);
     logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __li + " ]: lookup_manager - [1/10] JDBC credentials loaded. usernamePresent=" + (username != null && username !== "") + ", passwordPresent=" + (password != null && password !== ""));

} catch (e) {
    logger.error("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __li + " ]: lookup_manager - [1/10] Error processing JDBC secret: " + e.message);
}

/********************************************
    2 FETCH DATA LEDGER API KEY (Plain text)
********************************************/

try {
    var dataLedgerKey = LookupHelper.get("Config-sensitive", "TECHBD_NYEC_DATALEDGER_API_KEY");

     channelMap.put("TECHBD_NYEC_DATALEDGER_API_KEY", dataLedgerKey);
     globalMap.put("TECHBD_NYEC_DATALEDGER_API_KEY", dataLedgerKey);
     logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __li + " ]: lookup_manager - [2/10] Data Ledger API key loaded. present=" + (dataLedgerKey != null && dataLedgerKey !== ""));

} catch (e) {
    logger.error("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __li + " ]: lookup_manager - [2/10] Error processing DataLedger API Key secret: " + e.message);
}

/********************************************
    3 FETCH FHIR BUNDLE SUBMISSION API URL (Plain text)
********************************************/
try {
    var fhirChannelUrl = LookupHelper.get("Config", "MC_FHIR_BUNDLE_SUBMISSION_API_URL");

    if (!fhirChannelUrl || fhirChannelUrl.trim() === "") {
        throw "FHIR Channel URL retrieved from Lookup Manager is empty.";
    }
    channelMap.put("FHIR_CHANNEL_URL", fhirChannelUrl);
    globalMap.put("fhirChannelUrl", fhirChannelUrl);
    logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __li + " ]: lookup_manager - [3/10] FHIR_CHANNEL_URL loaded: " + fhirChannelUrl);

} catch (e) {
    logger.error("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __li + " ]: lookup_manager - [3/10] Error fetching FHIR CHANNEL URL: " + e);
    setErrorResponse(500, "Failed to load FHIR CHANNEL URL");
    throw e;
}

/********************************************
    4 FETCH JDBC URL (Plain text)
********************************************/
try {
    var jdbcUrl = LookupHelper.get("Config-sensitive", "MC_JDBC_URL");

    if (!jdbcUrl || jdbcUrl.trim() === "") {
        throw " MC_JDBC_URL retrieved from Lookup Manager is empty.";
    }
    jdbcUrl = jdbcUrl.trim(); // IMPORTANT: remove trailing spaces
     globalMap.put("jdbcUrl", jdbcUrl);
     logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __li + " ]: lookup_manager - [4/10] JDBC URL loaded successfully.");


} catch (e) {
    logger.error("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __li + " ]: lookup_manager - [4/10] Error fetching JDBC URL: " + e);
    setErrorResponse(500, "Failed to load JDBC URL");
    throw e;
}

/********************************************
    5 FETCH DEFAULT DATALAKE API URL (Plain text)
********************************************/
var rawHeader = $('headers').getHeader('X-TechBD-DataLake-API-URL');
var incomingHeader = rawHeader == null ? "" : String(rawHeader).trim();
var allowedUrlsConfig = LookupHelper.get(

    "Config",

    "TECHBD_DEFAULT_DATALAKE_API_URL"

);


if (!allowedUrlsConfig || String(allowedUrlsConfig).trim() === "") {

    throw "TECHBD_DEFAULT_DATALAKE_API_URL is empty.";

}
allowedUrlsConfig = String(allowedUrlsConfig).trim();
if (incomingHeader !== "") {

    var allowedUrls = allowedUrlsConfig.split(",");
    var isAllowed = false;
    for (var i = 0; i < allowedUrls.length; i++) {

        var allowedUrl = String(allowedUrls[i]).trim();
        logger.info(

            "Comparing incoming=[" +

            incomingHeader +

            "] with allowed=[" +

            allowedUrl +

            "]"

        );
        if (incomingHeader === allowedUrl) {

            isAllowed = true;

            break;

        }

    }
    if (!isAllowed) {

        logger.error(

            "Rejected DataLake API URL. Incoming: " +

            incomingHeader +

            ", Allowed URLs: " +

            allowedUrlsConfig

        );
        setErrorResponse(

            400,

            "Invalid X-TechBD-DataLake-API-URL. Only approved DataLake URL is allowed."

        );
        throw "SSRF validation failed";

    }
    datalakeApiUrl = incomingHeader;

} else {

    // Use first URL from whitelist as default

    datalakeApiUrl = String(

        allowedUrlsConfig.split(",")[0]

    ).trim();

}
channelMap.put("DATALAKE_API_URL", datalakeApiUrl);
logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __li + " ]: lookup_manager - [5/10] DATALAKE_API_URL resolved: " + datalakeApiUrl);
/********************************************
    6 FETCH DATA LAKE API KEY (Plain text)
********************************************/

try {
    var dataLakeApiKey = LookupHelper.get("Config-sensitive", "TECHBD_NYEC_DATALAKE_API_KEY");

    channelMap.put("DATA_LAKE_API_KEY", dataLakeApiKey);
    logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __li + " ]: lookup_manager - [6/10] DataLake API key loaded. present=" + (dataLakeApiKey != null && dataLakeApiKey !== ""));

} catch (e) {
    logger.error("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __li + " ]: lookup_manager - [6/10] Error processing DataLake API Key secret: " + e.message);
}


/********************************************
    7 FETCH FHIR BUNDLE VALIDATION API URL (Plain text)
********************************************/
try {
    var fhirApiUrl = LookupHelper.get("Config", "BL_FHIR_BUNDLE_VALIDATION_API_URL");

    if (!fhirApiUrl || fhirApiUrl.trim() === "") {
        throw " BL FHIR Bundle Validation API URL retrieved from Lookup Manager is empty.";
    }
	fhirApiUrl = fhirApiUrl + "/Bundle/$validate";
    channelMap.put("FHIR_API_URL", fhirApiUrl);
    logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __li + " ]: lookup_manager - [7/10] FHIR_API_URL resolved: " + fhirApiUrl);


} catch (e) {
    logger.error("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __li + " ]: lookup_manager - [7/10] Error fetching FHIR API URL: " + e);
    setErrorResponse(500, "Failed to load FHIR API URL");
    throw e;
}

/********************************************
    8 FETCH DATA LEDGER API URL (Plain text)
********************************************/

try {
    var dataLedgerApiUrl = LookupHelper.get("Config", "DATA_LEDGER_API_URL");

     channelMap.put("DATA_LEDGER_API_URL", dataLedgerApiUrl);
     globalMap.put("DATA_LEDGER_API_URL", dataLedgerApiUrl);
     logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __li + " ]: lookup_manager - [8/10] DATA_LEDGER_API_URL resolved: " + dataLedgerApiUrl);

} catch (e) {
    logger.error("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __li + " ]: lookup_manager - [8/10] Error processing DataLedger API URL secret: " + e.message);
}

/********************************************
    9 FETCH DATA LEDGER TRACKING (Plain text)
********************************************/

try {
    var dataLedgerTracking = LookupHelper.get("Config", "DATA_LEDGER_TRACKING");

    channelMap.put("DATA_LEDGER_TRACKING", dataLedgerTracking);
    channelMap.put("dataLedgerTracking", dataLedgerTracking);
    globalMap.put("DATA_LEDGER_TRACKING", dataLedgerTracking);
    logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __li + " ]: lookup_manager - [9/10] DATA_LEDGER_TRACKING resolved: " + dataLedgerTracking);

} catch (e) {
    logger.error("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __li + " ]: lookup_manager - [9/10] Error processing DataLedger Tracking secret: " + e.message);
}

/********************************************
    9 FETCH DATA LEDGER DIAGNOSTICS (Plain text)
********************************************/

try {
    var dataLedgerDiagnostics = LookupHelper.get("Config", "DATA_LEDGER_DIAGNOSTICS");

    channelMap.put("DATA_LEDGER_DIAGNOSTICS", dataLedgerDiagnostics);
    channelMap.put("dataLedgerDiagnostics", dataLedgerDiagnostics);
    globalMap.put("DATA_LEDGER_DIAGNOSTICS", dataLedgerDiagnostics);
    logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __li + " ]: lookup_manager - [9/10] DATA_LEDGER_DIAGNOSTICS resolved: " + dataLedgerDiagnostics);

} catch (e) {
    logger.error("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __li + " ]: lookup_manager - [9/10] Error processing DataLedger diagnostics secret: " + e.message);
}

/********************************************
    10 FETCH HUB UI URL (Plain text)
********************************************/
try {
    var hubUiUrl = LookupHelper.get("Config", "HUB_UI_URL");


    if (!hubUiUrl || hubUiUrl.trim() === "") {
        throw "HUB UI URL retrieved from Lookup Manager is empty.";
    }
    hubUiUrl = hubUiUrl.trim();
    channelMap.put("HUB_UI_URL", hubUiUrl);
    globalMap.put("HUB_UI_URL", hubUiUrl);
    logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __li + " ]: lookup_manager - [10/10] HUB_UI_URL resolved: " + hubUiUrl);

} catch (e) {
    logger.error("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __li + " ]: lookup_manager - [10/10] Error fetching HUB UI URL: " + e);
    setErrorResponse(500, "Failed to load HUB UI URL");
    throw e;
}

/*******************************
    Processing Agent Loader
********************************/

try {
	//value is either true or false
    var processingFeatureEnable = LookupHelper.get("Config", "ORG_TECHBD_PROCESSING_AGENT_FEATURE_ENABLED");

    channelMap.put("ORG_TECHBD_PROCESSING_AGENT_FEATURE_ENABLED", processingFeatureEnable);
    globalMap.put("ORG_TECHBD_PROCESSING_AGENT_FEATURE_ENABLED", processingFeatureEnable);
    logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __li + " ]: lookup_manager - Processing Agent Loader: featureEnabled=" + processingFeatureEnable);

} catch (e) {
    logger.error("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __li + " ]: lookup_manager - Error fetching processing feature enable flag: " + e.message);
}

try {
	//values will be comma seperated tenant ids eg:abc,xyz,test
    var processingAgentTenantIds = LookupHelper.get("Config", "ORG_TECHBD_PROCESSING_AGENT_TENANT_IDS");

    channelMap.put("ORG_TECHBD_PROCESSING_AGENT_TENANT_IDS", processingAgentTenantIds);
    globalMap.put("ORG_TECHBD_PROCESSING_AGENT_TENANT_IDS", processingAgentTenantIds);
    logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __li + " ]: lookup_manager - Processing Agent Loader: tenantIds=" + processingAgentTenantIds);

} catch (e) {
    logger.error("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __li + " ]: lookup_manager - Error fetching processing agent tenant ids: " + e.message);
}

try {
	//value is TXD
    var processingAgentValue = LookupHelper.get("Config", "ORG_TECHBD_PROCESSING_AGENT_VALUE");

    channelMap.put("ORG_TECHBD_PROCESSING_AGENT_VALUE", processingAgentValue);
    globalMap.put("ORG_TECHBD_PROCESSING_AGENT_VALUE", processingAgentValue);
    logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __li + " ]: lookup_manager - Processing Agent Loader: agentValue=" + processingAgentValue);

} catch (e) {
    logger.error("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __li + " ]: lookup_manager - Error fetching processing agent value: " + e.message);
}

logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __li + " ]: STEP lookup_manager - END.");
/********************************************
    DONE
********************************************/

// Use logger.info with a single string (no channelMap arg)
var __fvLi = channelMap.get('interactionId');
logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __fvLi + " ]: STEP FHIR Validation - START.");

var requestedPath = channelMap.get('requestedPath');
channelMap.put("requestUri", requestedPath);
logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __fvLi + " ]: FHIR Validation - requestedPath=" + requestedPath);


if (
    requestedPath == "/"
) {
    logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __fvLi + " ]: FHIR Validation - path is root, nothing to do, returning.");
    return;
}
logger.info("requestedPath"+requestedPath);

if (requestedPath == "/tenants" || requestedPath == "/tenants/") {

    logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __fvLi + " ]: FHIR Validation - handling /tenants lookup.");
    importPackage(java.sql);

    var conn = null;
    var stmt = null;
    var rs = null;

    try {

        conn = DriverManager.getConnection(
            globalMap.get("jdbcUrl"),
            globalMap.get("jdbcUsername"),
            globalMap.get("jdbcPassword")
        );
        logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __fvLi + " ]: FHIR Validation - /tenants DB connection established.");

        stmt = conn.createStatement();

        rs = stmt.executeQuery(
            "SELECT * FROM techbd_udi_ingress.get_active_tenants()"
        );

        var tenants = [];

        while (rs.next()) {

            tenants.push({
                tenantId: rs.getString("p_tenant_id"),
                tenantName: rs.getString("p_tenant_name"),
                tenantType: rs.getString("p_tenant_type")
            });

        }

        channelMap.put("tenantResponse", JSON.stringify(tenants));
        logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __fvLi + " ]: FHIR Validation - /tenants returned " + tenants.length + " active tenant(s).");

    } finally {

        if (rs != null) rs.close();
        if (stmt != null) stmt.close();
        if (conn != null) conn.close();
        logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __fvLi + " ]: FHIR Validation - /tenants DB connection closed.");
    }
    logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __fvLi + " ]: STEP FHIR Validation - END (tenants).");
    return;
}

// This step is reached only for the historical-replay Bundle path (filter already
// restricted methods/paths), so the remainder handles that submission.
logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __fvLi + " ]: FHIR Validation - handling historical-replay Bundle submission.");
var fhirJson  = connectorMessage.getRawData();
channelMap.put('fhirJson', fhirJson);
logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + __fvLi + " ]: FHIR Validation - fhirJson captured, length=" + (fhirJson != null ? String(fhirJson).length : 0));


var interactionId = channelMap.get('interactionId');
var validationSeverityLevel = channelMap.get('validationSeverityLevel');
var source = channelMap.get('source');
var igVersion = channelMap.get('igVersion');
var elaboration = channelMap.get('elaboration');
var groupInteractionId = channelMap.get('groupInteractionId');
var masterInteractionId = channelMap.get('masterInteractionId');
var healthCheck = channelMap.get('healthCheck');


channelMap.put('interactionId', interactionId);
channelMap.put("validationSeverityLevel",validationSeverityLevel);
channelMap.put('source',source);
channelMap.put('igVersion', igVersion);
channelMap.put('elaboration', elaboration);
channelMap.put('groupInteractionId', groupInteractionId);
channelMap.put('masterInteractionId', masterInteractionId);

var tenantId = $('headers').getHeader('X-TechBD-Tenant-ID');
channelMap.put('tenantId', tenantId);

var userAgent = channelMap.get('userAgent');
channelMap.put('userAgent', userAgent);

logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + interactionId + " ]: FHIR Validation - context: tenantId=" + tenantId + ", source=" + source + ", igVersion=" + igVersion + ", validationSeverityLevel=" + validationSeverityLevel + ", ooSize=" + channelMap.get('ooSize') + ", dataLedgerParam=" + channelMap.get('dataLedgerParam') + ", groupInteractionId=" + groupInteractionId + ", masterInteractionId=" + masterInteractionId);

channelMap.put("endpoint", "submission");
responseMap.put('status', '200'); // Set HTTP status 200
logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + interactionId + " ]: STEP FHIR Validation - END (submission ready to forward to dest_bundle).");

com.mirth.connect.plugins.javascriptrule.script:
var httpMethod = String(sourceMap.get('method')).toUpperCase();
var contextPath = String(connectorMessage.getSourceMap().get('contextPath')).replace(/\/$/, '');

/**
 * Util function to generate JSON string
 */
function createJsonResponse(status, message) {
    return JSON.stringify({ status: status, message: message });
}

/**
 * Util function to set error response
 */
function setErrorResponse(statusCode, errorMessage) {
    responseMap.put('status', String(statusCode));
    responseMap.put('message', errorMessage);
    responseMap.put('finalResponse', createJsonResponse(statusCode, errorMessage));
}

logger.info(
    "DEBUG -> Method inside fhir historical-replay channel: " + httpMethod +
    ", Path: " + contextPath
);

/* =====================================
   1 ROOT ENDPOINT
===================================== */
if (contextPath === '') {

   if (httpMethod === 'GET') {

    logger.info("DEBUG -> Filter: routing to ROOT endpoint, method=GET -> 200 OK, short-circuit");
    responseMap.put('responseStatusCode', 200);
    responseMap.put('responseContentType', 'application/json');
    responseMap.put('responseBody', JSON.stringify({
        status: 200,
        message: "OK"
    }));

   return false;
}

    // Method not allowed for /
    logger.info("DEBUG -> Filter: ROOT endpoint hit with unsupported method=" + httpMethod);
    return methodNotAllowed();
}

/* =====================================
   2 HEALTHCHECK
===================================== */
if (contextPath === '/healthcheck') {

    if (httpMethod === 'GET') {
         logger.info("DEBUG -> Filter: routing to HEALTHCHECK endpoint -> 200 OK, short-circuit");
         responseMap.put('responseStatusCode', 200);
	    responseMap.put('responseContentType', 'application/json');
	    responseMap.put('responseBody', JSON.stringify({
	        status: 200,
	        message: "OK"
	    }));

	   return false;
    }

    logger.info("DEBUG -> Filter: HEALTHCHECK endpoint hit with unsupported method=" + httpMethod);
    return methodNotAllowed();
}

/* =====================================
   3 TENANTS
===================================== */

if (contextPath === '/tenants' || contextPath === '/tenants/') {

    if (httpMethod === 'GET') {
        logger.info("DEBUG -> Filter: routing to TENANTS endpoint -> passing through to transformer");
        channelMap.put("endpoint", "tenants");
        return true;
    }

    logger.info("DEBUG -> Filter: TENANTS endpoint hit with unsupported method=" + httpMethod);
    return methodNotAllowed();
}

/* =====================================
   4 HISTORICAL REPLAY BUNDLE
===================================== */
if (contextPath === '/historical-replay/Bundle/' || contextPath === '/historical-replay/Bundle') {

    if (httpMethod === 'POST' || httpMethod === 'OPTIONS') {
        logger.info("DEBUG -> Filter: routing to HISTORICAL-REPLAY BUNDLE endpoint, method=" + httpMethod + " -> passing through to transformer");
        return true;
    }

    logger.info("DEBUG -> Filter: HISTORICAL-REPLAY BUNDLE endpoint hit with unsupported method=" + httpMethod);
    return methodNotAllowed();
}



/* =====================================
   INVALID PATH -> 404
===================================== */
logger.info("DEBUG -> Filter: no route matched for path=" + contextPath + ", method=" + httpMethod + " -> 404");
return notFound();




/* =====================================
   Helper Functions
===================================== */

function methodNotAllowed() {

    var errorResponse = "Method Not Allowed.";
    logger.error("DEBUG -> Filter: returning 405 - " + errorResponse);

    responseMap.put('responseStatusCode', 405);
    responseMap.put('responseContentType', 'application/json');
    responseMap.put('responseBody', JSON.stringify(errorResponse));

    setErrorResponse(405, errorResponse);

    throw "Invalid method";
}

function notFound() {

    var errorResponse = "Not Found: Invalid endpoint.";
    logger.error("DEBUG -> Filter: returning 404 - " + errorResponse);

    responseMap.put('responseStatusCode', 404);
    responseMap.put('responseContentType', 'application/json');
    responseMap.put('responseBody', JSON.stringify(errorResponse));

    setErrorResponse(404, errorResponse);

    throw "Invalid endpoint";
}

properties.script:
// ------------------------------------------------------------
// Resolve Processing Agent (Same logic as Java service)
// ------------------------------------------------------------
function resolveProcessingAgent(tenantId) {

    var featureEnabled = String(globalMap.get("ORG_TECHBD_PROCESSING_AGENT_FEATURE_ENABLED"));
    var tenantIds = String(globalMap.get("ORG_TECHBD_PROCESSING_AGENT_TENANT_IDS"));
    var value = String(globalMap.get("ORG_TECHBD_PROCESSING_AGENT_VALUE"));
    tenantId = String(tenantId);

    logger.info("Feature Flag: " + featureEnabled+"Tenant IDs Config: " + tenantIds+"Configured Value: " + value+"Incoming TenantId: [" + tenantId + "]");


    if (!tenantId || featureEnabled !== "true") {
        logger.info("Feature disabled or tenantId missing");
        return tenantId;
    }

    var incomingTenant = tenantId.trim().toLowerCase();
    var tenantList = tenantIds.split(",");


    for (var i = 0; i < tenantList.length; i++) {

        var configTenant = String(tenantList[i]).trim().toLowerCase();

        if (configTenant === incomingTenant) {
            logger.info("Tenant matched. Returning value: " + value);
            return value;
        }
    }

    return tenantId;
}


// ------------------------------------------------------------
// Apache HttpClient Imports
// ------------------------------------------------------------
var DefaultHttpClient = Packages.org.apache.http.impl.client.DefaultHttpClient;
var HttpPost = Packages.org.apache.http.client.methods.HttpPost;
var StringEntity = Packages.org.apache.http.entity.StringEntity;
var EntityUtils = Packages.org.apache.http.util.EntityUtils;

// ------------------------------------------------------------
// Get Required Values
// ------------------------------------------------------------
var datalakeApiUrl = channelMap.get("DATALAKE_API_URL");
var tenantId = channelMap.get('tenantId');
var apiKey = channelMap.get("DATA_LAKE_API_KEY");

if (!datalakeApiUrl) {
    throw "DATALAKE_API_URL is missing";
}

if (!tenantId) {
    throw "Tenant ID is missing";
}

if (!apiKey) {
    throw "DATA_LAKE_API_KEY is missing";
}

// ------------------------------------------------------------
// Build Final URL
// ------------------------------------------------------------

var processingAgent = resolveProcessingAgent(tenantId);
var finalUrl = datalakeApiUrl + "?processingAgent=" + processingAgent;
logger.info("Calling DataLake URL: " + finalUrl);

// ------------------------------------------------------------
// Create HTTP Client
// ------------------------------------------------------------
var client = new DefaultHttpClient();
var post = new HttpPost(finalUrl);

// ------------------------------------------------------------
// Set Headers
// ------------------------------------------------------------
post.setHeader("X-TechBD-Tenant-ID", tenantId);
post.setHeader("Content-Type", "application/fhir+json");
post.setHeader("x-api-key", apiKey);

// ------------------------------------------------------------
// Set Request Body
// ------------------------------------------------------------
var payloadMsg = channelMap.get('updatedFhirJson');
var payload = payloadMsg;
post.setEntity(new StringEntity(payload, "UTF-8"));

// ------------------------------------------------------------
// Execute Request
// ------------------------------------------------------------
var statusCode = 500;
var statusText = "";
var responseBody = "";
dataLakeErrorMessage = "";

try {

    var response = client.execute(post);

    var statusLine = response.getStatusLine();
    statusCode = statusLine.getStatusCode();
    statusText = statusLine.getReasonPhrase();

    if (response.getEntity() != null) {
        responseBody = EntityUtils.toString(response.getEntity(), "UTF-8");
    }

    logger.info("DataLake Status Code: " + statusCode+"DataLake Status Text: " + statusText+"DataLake Response Body: " + responseBody);

} catch (e) {

    logger.error("Error calling DataLake API: " + e);
    var bundleAsyncInteractionId = channelMap.get("interactionId");
    var dataLakeApiBaseURL = datalakeApiUrl;

    logger.error(
        "NYEC_API_CALL_FAILED " +
        "REGISTER State Fail" +
        " : Register State Failure - Exception while sending FHIR payload to datalake URL " +
        dataLakeApiBaseURL +
        " for interaction id " +
        bundleAsyncInteractionId +
        " error: " + e
    );

    statusCode = 500;

    var errMsg = "";
    if (e.javaException) {
        errMsg = e.javaException.getMessage();
    } else if (e.message) {
        errMsg = e.message;
    } else {
        errMsg = e.toString();
    }

    logger.info("Error Message: " + errMsg);

    // Detect UnknownHostException
    if (e.javaException && e.javaException instanceof java.net.UnknownHostException) {
        var host = String(datalakeApiUrl).replace(/^https?:\/\//, '').split("/")[0];
        errMsg = "Failed to resolve '" + host + "'";
    }

    statusText = "Exception";

    // keep original body
    responseBody = e.toString();

    // store clean message
    dataLakeErrorMessage = errMsg;
}

// ------------------------------------------------------------
// Store For Postprocessor
// ------------------------------------------------------------
channelMap.put("datalake_status_code", statusCode);
channelMap.put("datalake_status_text", statusText);
channelMap.put("datalake_response_body", responseBody);
channelMap.put("datalake_response_message", dataLakeErrorMessage);

return;

com.mirth.connect.plugins.javascriptstep.script:
// ---------------------- BEGIN: integrated helper + usage block ----------------------
logger.info("DESTINATION STARTS ###");

var Instant = Packages.java.time.Instant;
var Duration = Packages.java.time.Duration;




var source = channelMap.get("source");
var interactionId = channelMap.get("interactionId");
var validationSeverityLevel = channelMap.get("validationSeverityLevel");
var saveFHIRPayload = globalMap.get('saveFHIRPayload');
var sendDataLedgerSync = globalMap.get('sendDataLedgerSync');
var tenantId = $('headers').getHeader('X-TechBD-Tenant-ID');
var actionDiscard = "";
channelMap.put('isActionDiscard', "discard");

var requestUri = channelMap.get("requestUri");

// ---- Historical Replay params (set in preprocessor) ----
var ooSizeParam = channelMap.get('ooSize');
if (ooSizeParam == null || ooSizeParam === '') { ooSizeParam = 'full'; }
var dataLedgerParamFlag = channelMap.get('dataLedgerParam');
if (dataLedgerParamFlag == null || dataLedgerParamFlag === '') { dataLedgerParamFlag = 'true'; }

logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: destination_datalake STARTS | tenantId=" + tenantId + ", requestUri=" + requestUri + ", ooSize=" + ooSizeParam + ", dataLedgerParam=" + dataLedgerParamFlag + ", validationSeverityLevel=" + validationSeverityLevel);


// Safe single-parse helper (handles java.lang.String)
function parseOnceMaybeString(v) {
    if (v === null || v === undefined) return null;
    try {
        if (typeof v === 'string') return JSON.parse(v);
        if (v && v.getClass && v.getClass().getName && (v.getClass().getName().indexOf('String') !== -1 || v.getClass().getName().indexOf('StringBuilder') !== -1)) {
            return JSON.parse(v.toString());
        }
        if (typeof v === 'object') return v;
    } catch (e) {
        try { logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: parseOnceMaybeString: JSON.parse failed: " + e); } catch(ignore){}
        return null;
    }
    return null;
}



// extractIssueAndDisposition(operationOutcomePayload, severityLevel)
// severityLevel controls the threshold used to filter issue[] (fatal / fatal+error / fatal+error+warning / all)
function extractIssueAndDisposition(operationOutcomePayload, severityLevel) {
    if (operationOutcomePayload === null || operationOutcomePayload === undefined) {
        try { logger.warn("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: extractIssueAndDisposition: operationOutcomePayload is null/undefined"); } catch(e){}
        return null;
    }
    var payloadObj = parseOnceMaybeString(operationOutcomePayload);
    if (!payloadObj && operationOutcomePayload && typeof operationOutcomePayload === 'object') payloadObj = operationOutcomePayload;
    if (!payloadObj || typeof payloadObj !== 'object') {
        try { logger.warn("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: extractIssueAndDisposition: payload not parseable as object"); } catch(e){}
        return null;
    }

    // tolerate OperationOutcome or operationOutcome key
    var operationOutcomeMap = payloadObj.OperationOutcome !== undefined ? payloadObj.OperationOutcome
                             : (payloadObj.operationOutcome !== undefined ? payloadObj.operationOutcome : null);

    if (!operationOutcomeMap || typeof operationOutcomeMap !== 'object') {
        try { logger.warn("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]:extractIssueAndDisposition: OperationOutcome map missing"); } catch(e){}
        return null;
    }

    // validationResults
    var validationResults = operationOutcomeMap.validationResults !== undefined ? operationOutcomeMap.validationResults
                          : (operationOutcomeMap.get ? operationOutcomeMap.get('validationResults') : null);

    if (!validationResults || !(validationResults instanceof Array) || validationResults.length === 0) {
        try { logger.warn("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: extractIssueAndDisposition: validationResults missing or empty"); } catch(e){}
        return null;
    }

    var validationResult = validationResults[0];
    if (!validationResult || typeof validationResult !== 'object') {
        try { logger.warn("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]:extractIssueAndDisposition: first validationResult missing or not an object"); } catch(e){}
        return null;
    }

    var innerOperationOutcome = validationResult.operationOutcome !== undefined ? validationResult.operationOutcome
                              : (validationResult.get ? validationResult.get('operationOutcome') : null);

    var issuesRaw = innerOperationOutcome && innerOperationOutcome.issue !== undefined ? innerOperationOutcome.issue
                  : (innerOperationOutcome && innerOperationOutcome.get ? innerOperationOutcome.get('issue') : null);

    // severity threshold (default to "error" if not provided)
	   var sev = (severityLevel && String(severityLevel).trim().length > 0)
    ? String(severityLevel).trim().toLowerCase()
    : 'error';


   logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]:  Severity level (sev): " + sev);
    var allowedSeverities;
    switch (sev) {
        case 'fatal':
            allowedSeverities = new Set(['fatal']);
            break;
        case 'warning':
            allowedSeverities = new Set(['fatal','error','warning']);
            break;
        case 'information':
            allowedSeverities = new Set(['fatal','error','warning','information']);
            break;
        case 'error':
        default:
            allowedSeverities = new Set(['fatal','error']);
            break;
    }

    var filteredIssues = [];
    if (issuesRaw && issuesRaw instanceof Array) {
        for (var i = 0; i < issuesRaw.length; i++) {
            var issue = issuesRaw[i];
            if (!issue || typeof issue !== 'object') continue;
            var severity = issue.severity !== undefined ? issue.severity : (issue.get ? issue.get('severity') : null);
            if (severity && allowedSeverities.has(severity.toLowerCase())) {

                filteredIssues.push(issue);
            }
        }
    }

    if (filteredIssues.length === 0) {
    	var validSeverities = new Set(['fatal','error','warning','information']);
    	var displaySeverity = validSeverities.has(sev)
      ? sev
      : 'error';
        var infoIssue = { severity: 'information',
                          diagnostics: 'Validation successful. No issues found at or above severity level: ' + displaySeverity,
                          code: 'informational' };
        filteredIssues.push(infoIssue);
    }

    var result = {};
    try {
        result.resourceType = operationOutcomeMap.resourceType !== undefined ? operationOutcomeMap.resourceType
                             : (operationOutcomeMap.get ? operationOutcomeMap.get('resourceType') : undefined);
    } catch(e) { result.resourceType = undefined; }

    result.issue = filteredIssues;

    try {
        var tbd = operationOutcomeMap.techByDesignDisposition !== undefined ? operationOutcomeMap.techByDesignDisposition
                  : (operationOutcomeMap.get ? operationOutcomeMap.get('techByDesignDisposition') : null);
        if (tbd) result.techByDesignDisposition = tbd;
    } catch(e) {}

    return result;
}

// applyOoSizeFilter(result, ooSize) - JS mirror of the Java
// HistoricalReplayService#applyOoSizeFilter method. Operates on the FULL parsed
// dest_bundle response (root object with an "OperationOutcome" key containing
// "validationResults"), NOT on the flattened object extractIssueAndDisposition()
// returns - that function is unchanged and continues to only affect what gets
// forwarded to DataLake above.
//  - ooSize "full" (default), or result == null -> returned unchanged.
//  - ooSize "none" -> returns null (caller responds with just the interactionId).
//  - ooSize "lite" -> keeps only fatal/error issues inside every
//        OperationOutcome.validationResults[*].operationOutcome.issue array.
//  - any other/unexpected shape -> fail-open, returned unchanged.
function applyOoSizeFilter(result, ooSize) {
    var normalizedOoSize = (ooSize != null && String(ooSize).trim() !== '') ? String(ooSize).trim().toLowerCase() : 'full';
    logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: applyOoSizeFilter STARTS -> normalizedOoSize=" + normalizedOoSize + ", resultIsNull=" + (result == null));

    if (normalizedOoSize === 'full' || result == null) {
        logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: applyOoSizeFilter: full (or null result) -> returning result unchanged");
        return result;
    }
    if (normalizedOoSize === 'none') {
        logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: applyOoSizeFilter: none -> returning null");
        return null;
    }
    if (normalizedOoSize !== 'lite' || typeof result !== 'object') {
        logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: applyOoSizeFilter: not lite, or result not an object -> returning result unchanged");
        return result;
    }

    // lite: keep only error/fatal issues inside OperationOutcome.validationResults[*].operationOutcome.issue
    try {
        var root = {};
        for (var rk in result) { if (Object.prototype.hasOwnProperty.call(result, rk)) root[rk] = result[rk]; }

        var ooObj = root['OperationOutcome'];
        if (!ooObj || typeof ooObj !== 'object') {
            logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: applyOoSizeFilter: lite - no OperationOutcome present, returning result unchanged");
            return result;
        }
        var oo = {};
        for (var ok in ooObj) { if (Object.prototype.hasOwnProperty.call(ooObj, ok)) oo[ok] = ooObj[ok]; }

        var vrObj = oo['validationResults'];
        if (!(vrObj instanceof Array)) {
            logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: applyOoSizeFilter: lite - validationResults missing/not an array, returning result unchanged");
            return result;
        }

        var filteredVr = [];
        for (var i = 0; i < vrObj.length; i++) {
            var vrItem = vrObj[i];
            if (!vrItem || typeof vrItem !== 'object') {
                filteredVr.push(vrItem);
                continue;
            }
            var vr = {};
            for (var vk in vrItem) { if (Object.prototype.hasOwnProperty.call(vrItem, vk)) vr[vk] = vrItem[vk]; }

            var innerOoObj = vr['operationOutcome'];
            if (innerOoObj && typeof innerOoObj === 'object') {
                var innerOo = {};
                for (var ik in innerOoObj) { if (Object.prototype.hasOwnProperty.call(innerOoObj, ik)) innerOo[ik] = innerOoObj[ik]; }

                var issuesObj = innerOo['issue'];
                if (issuesObj instanceof Array) {
                    var errorsOnly = [];
                    for (var j = 0; j < issuesObj.length; j++) {
                        var iss = issuesObj[j];
                        if (iss && typeof iss === 'object') {
                            var sev = String(iss['severity']);
                            if (sev.toLowerCase() === 'error' || sev.toLowerCase() === 'fatal') {
                                errorsOnly.push(iss);
                            }
                        }
                    }
                    logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: applyOoSizeFilter: lite - validationResults[" + i + "] issue count " + issuesObj.length + " -> " + errorsOnly.length + " after filtering to fatal/error");
                    innerOo['issue'] = errorsOnly;
                }
                vr['operationOutcome'] = innerOo;
            }
            filteredVr.push(vr);
        }
        oo['validationResults'] = filteredVr;
        root['OperationOutcome'] = oo;
        logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: applyOoSizeFilter ENDS -> lite filtering applied successfully");
        return root;
    } catch (e) {
        logger.warn("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: applyOoSizeFilter failed, returning original unfiltered result: " + e.message);
        return result;
    }
}

// appendToBundlePayload(payload, extractedOutcome) mirror of your Java method
function appendToBundlePayload(payload, extractedOutcome) {
    var bundleObj = parseOnceMaybeString(payload);
    if (!bundleObj && payload && typeof payload === 'object') bundleObj = payload;
    if (!bundleObj || typeof bundleObj !== 'object') {
        bundleObj = { entry: [] };
        try { logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: appendToBundlePayload: created new bundle because payload was missing/unparseable"); } catch(e){}
    }
    if (!bundleObj.entry || !(bundleObj.entry instanceof Array)) bundleObj.entry = [];

    var parsedOutcome = (extractedOutcome === null || extractedOutcome === undefined) ? null : extractedOutcome;
    // if outcome could be a string, try parse once (function above)
    var tryParsed = parseOnceMaybeString(parsedOutcome);
    if (tryParsed) parsedOutcome = tryParsed;
    if (!parsedOutcome && parsedOutcome !== null && typeof parsedOutcome === 'object') parsedOutcome = parsedOutcome;

    var newEntry = { resource: parsedOutcome };
    bundleObj.entry.push(newEntry);

    // return shallow copy (similar to Java new HashMap<>(payload) and put entry)
    var finalPayload = {};
    for (var k in bundleObj) {
        if (Object.prototype.hasOwnProperty.call(bundleObj, k)) finalPayload[k] = bundleObj[k];
    }
    return finalPayload;
}


function isActionDiscard(updatedPayload) {
    // helper to read property from Java Map or JS object
    function getProp(obj, key) {
        if (obj == null) return null;
        if (typeof obj.get === 'function') {
            try { return obj.get(key); } catch(e) { return null; }
        }
        return obj[key];
    }

    // helper to iterate a java.util.List or JS Array
    function iterateList(list, fn) {
        if (list == null) return false;
        try {
            if (typeof list.size === 'function' && typeof list.get === 'function') {
                for (var i = 0; i < list.size(); i++) {
                    if (fn(list.get(i), i)) return true;
                }
                return false;
            } else if (Array.isArray(list)) {
                for (var j = 0; j < list.length; j++) {
                    if (fn(list[j], j)) return true;
                }
                return false;
            } else if (typeof list.iterator === 'function') {
                var it = list.iterator();
                var idx = 0;
                while (it.hasNext()) {
                    if (fn(it.next(), idx++)) return true;
                }
                return false;
            }
        } catch(e) {
            logger.error("iterateList error: " + e);
        }
        return false;
    }

    // normalize payload: if string try parse
    var obj = updatedPayload;
    if (typeof updatedPayload === 'string') {
        try {
            obj = JSON.parse(updatedPayload);
        } catch (e) {
            logger.info("isActionDiscard: payload is not valid JSON string");
            return false;
        }
    }

    // if payload itself is OperationOutcome (rare)
    var maybeOp = getProp(obj, 'OperationOutcome');
    if (maybeOp) {
        // if OperationOutcome is an object that contains techByDesignDisposition
        var dispositions = getProp(maybeOp, 'techByDesignDisposition');
        if (iterateList(dispositions, function(d) {
            var action = getProp(d, 'action');
            return action != null && String(action).trim().toLowerCase() === 'discard';
        })) return true;
    }

    // If this is a Bundle with entries, look in each entry.resource
    var entries = getProp(obj, 'entry');
    if (entries) {
        var found = iterateList(entries, function(entry) {
            var resource = getProp(entry, 'resource');
            if (!resource) return false;
            var rType = getProp(resource, 'resourceType');
            // check if this resource is OperationOutcome
            if (rType && String(rType).toLowerCase() === 'operationoutcome') {
                var dispositions = getProp(resource, 'techByDesignDisposition');
                return iterateList(dispositions, function(d) {
                    var action = getProp(d, 'action');
                    return action != null && String(action).trim().toLowerCase() === 'discard';
                });
            }
            return false;
        });
        if (found) return true;
    }

    // Also check top-level techByDesignDisposition if present directly on payload
    var topDispositions = getProp(obj, 'techByDesignDisposition');
    if (topDispositions) {
        if (iterateList(topDispositions, function(d) {
            var action = getProp(d, 'action');
            return action != null && String(action).trim().toLowerCase() === 'discard';
        })) return true;
    }

    return false;
}




// ---------------------- usage: extract rawResponseMsg, call functions and persist ----------------------

// 1) extract rawResponseMsg safely from responseMap
var destName = 'dest_bundle';
var rawResponseMsg = null;
try {
    var destResp = responseMap.get(destName);
    if (destResp) {
        if (typeof destResp.getMessage === 'function') {
            rawResponseMsg = destResp.getMessage();
        } else if (destResp.message !== undefined) {
            rawResponseMsg = destResp.message;
        } else {
            rawResponseMsg = destResp.toString();
        }
    } else {
        logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]:No response found in responseMap for " + destName);
    }
} catch (e) {
    rawResponseMsg = null;
    try { logger.warn("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]:Error while extracting rawResponseMsg: " + e); } catch(ignore){}
}

// 2) get rawFhir
var rawFhir = null;
try { rawFhir = channelMap.get('fhirJson'); } catch(e) { rawFhir = null; }

// 3) call extractIssueAndDisposition for the payload forwarded to DataLake
// (this filter is unchanged and continues to use the X-TechBD-Validation-Severity-Level header)

logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: Calling extractIssueAndDisposition (DataLake-forward filter) with validationSeverityLevel=" + validationSeverityLevel);
var extractedPayload = null;
try {
    extractedPayload = extractIssueAndDisposition(rawResponseMsg, validationSeverityLevel);
    logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: extractIssueAndDisposition returned " + (extractedPayload == null ? "null" : "a result") + " for DataLake forward");
} catch (e) {
    try { logger.error("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]:extractIssueAndDisposition threw: " + e); } catch(ignore){}
    extractedPayload = null;
}


try{
var bundleJson = JSON.parse(rawFhir);
// Extract bundle id
var bundleId = bundleJson.id ;
var dataId = interactionId;

	if (bundleId != null && bundleId.toString().trim().length > 0) {
		 dataId = bundleId;
	}
	logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: Resolved dataId=" + dataId + " (bundle.id present=" + (bundleId != null) + ")");
}catch (e) {
    logger.error("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: Invalid JSON payload received, aborting: " + e);
    var rawErrorResponse = JSON.stringify({
        error: "Invalid JSON payload",
        message: e.toString()
    });
    responseMap.put('finalResponse', rawResponseMsg);
    throw rawErrorResponse;
}


// 4) append to bundle if we got something
if (extractedPayload) {
    logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: extractedPayload present -> appending to bundle and continuing forward/DataLedger/DB flow");
    try {
        var updatedPayload = appendToBundlePayload(rawFhir, extractedPayload);
        logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: appendToBundlePayload complete");

		if (isActionDiscard(JSON.stringify(updatedPayload))) {
			logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: isActionDiscard=true -> will skip DataLedger/DB-forward for this interaction");
			channelMap.put('finalResponse', JSON.stringify(updatedPayload));
			channelMap.put('isActionDiscard', "discard");
			actionDiscard = "discard";
		}

		if (updatedPayload == null) {
			channelMap.put('finalResponse', JSON.stringify(updatedPayload));
			channelMap.put('isActionDiscard', "discard");
		}

	if( actionDiscard != "discard"){
        // persist updated bundle back (try channelMap first, fallback to responseMap)
        try {
            var updatedStr = JSON.stringify(updatedPayload);
            channelMap.put('updatedFhirJson', updatedStr);
            try {
		responseMap.put('updatedFhirJson', updatedStr);


		logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: DATA LEDGER STARTS");

		var currentTimestampBegin = new Date().toISOString().replace(/\.(\d{3})Z$/, function(match, millis) {
	    // Add 3 more random digits to simulate microseconds
	    var micros = millis + (Math.floor(Math.random() * 1000)).toString().padStart(3, '0');
	    return '.' + micros + 'Z';
	   });
		//save Datakledger starts
	var payloadDataLedger = JSON.stringify({
	        executedAt: currentTimestampBegin,
	        actor: "TechBD",
	        action: "sent",
	        destination: "NYeC",
	        dataId: dataId,
	        payloadType: "hrsnBundle"
	    });

		var trackingEnabled = channelMap.get("DATA_LEDGER_TRACKING");

		// Historical-replay: honor the dataLedger query parameter in addition to the
		// existing DATA_LEDGER_TRACKING config. dataLedger=false always skips the call,
		// dataLedger=true/omitted behaves exactly as today.
		if (trackingEnabled != null && trackingEnabled.toLowerCase() == "true" && dataLedgerParamFlag !== "false") {
		    logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]:data ledger api call -BEGIN received");
		    try {
		        sendDataLedgerSync(payloadDataLedger,interactionId);
		    } catch (e) {
		        logger.error("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]:Error occurred while sending data to Data Ledger: " + e.message);
		    }
		    logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]:data ledger api call -END received");
		} else {
		    logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]:DATA_LEDGER_TRACKING is not true or dataLedger query param is false; skipping Data Ledger sync. dataLedgerParam=" + dataLedgerParamFlag);
		}
		logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: DATA LEDGER ENDS");
		//save Datakledger ends
		channelMap.put('isActionDiscard', "");

		// Save to DB starts
		var operation = "saveForwardFHIRPayload";

		try{
			logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: REGISTER State Forward : BEGIN for inteaction id  : "+interactionId + " tenant id : " + tenantId);
			var start = Instant.now();

		     var operation = "saveForwardFHIRPayload";
		     var result = saveFHIRPayload(
			   interactionId,
			   tenantId,
			   requestUri ,
			   JSON.stringify(updatedPayload),
			   operation,source
			);
			var end = Instant.now();
			var elapsedMillis = Duration.between(start, end).toMillis();
			logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]:REGISTER State Forward : END for interaction id: "+interactionId + " tenant id: " + tenantId + ". Time taken: "+ elapsedMillis);
		} catch (e) {
			LOG.error("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]:ERROR:: REGISTER State Forward CALL for interaction id : "+interactionId + " tenant id : " + tenantId );
			var errorMsg;
	            if (e instanceof JavaException) {
	                errorMsg = "ERROR:: REGISTER State Forward CALL for interaction id : "+interactionId + " tenant id : " + tenantId + " :  " + e.toString();
	                throw errorMessage;
	            } else {
	                errorMsg = "Unexpected error during saving: " + e.message;
	                throw errorMessage;
	            }
		}

		/// Save to DB ends


            }
            catch (e) { responseMap.put('updatedFhirJson', updatedStr); logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: Saved updated bundle to responseMap.updatedFhirJson"); }
        } catch (e) {
            try { responseMap.put('updatedFhirJson', updatedStr); logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: Saved updated bundle object to responseMap.updatedFhirJson"); } catch(ignore){}
        }
	} // isActionDiscard

        // ---- Historical Replay: build the client-facing response based on ooSize ----
        // Mirrors HistoricalReplayService#applyOoSizeFilter (Java) plus the controller's
        // "if (filtered == null) return interactionId-only 200" check:
        //  - full (default), or a null/unparseable result -> unchanged (raw OperationOutcome).
        //  - lite -> keeps only fatal/error issues inside each
        //           OperationOutcome.validationResults[*].operationOutcome.issue entry.
        //  - none -> applyOoSizeFilter returns null explicitly.
        //  - Whenever the filtered result is null (ooSize=none, or nothing to return),
        //    respond HTTP 200 with just {"interactionId": ...} and no OperationOutcome body.
        logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: Building historical-replay client response. ooSize=" + ooSizeParam + ", dataLedgerParam=" + dataLedgerParamFlag);
        try {
            var parsedRawResponse = parseOnceMaybeString(rawResponseMsg);
            if (!parsedRawResponse && rawResponseMsg && typeof rawResponseMsg === 'object') {
                parsedRawResponse = rawResponseMsg;
            }
            logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: parsedRawResponse is " + (parsedRawResponse == null ? "null/unparseable" : "parsed OK"));

            var filteredResult = null;
            try {
                filteredResult = applyOoSizeFilter(parsedRawResponse, ooSizeParam);
            } catch (eFilter) {
                logger.error("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: applyOoSizeFilter threw, falling back to raw response: " + eFilter);
                filteredResult = parsedRawResponse;
            }

            if (filteredResult == null) {
                logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: Historical Replay returning HTTP 200 with EMPTY BODY | interactionId=" + interactionId);
                responseMap.put('finalResponse', JSON.stringify({ interactionId: interactionId }));
            } else {
                logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: Historical Replay returning HTTP 200 with OperationOutcome body for ooSize=" + ooSizeParam);
                responseMap.put('finalResponse', JSON.stringify(filteredResult));
            }
        } catch(eResp){
            logger.error("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: Unexpected error building historical-replay response, falling back to raw response: " + eResp);
            responseMap.put('finalResponse', rawResponseMsg);
        }
    } catch (e) {
        try { logger.error("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: Failed to append extractedPayload: " + e); } catch(ignore){}
    }
} else {
    try { logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: No extractedPayload produced — nothing appended."); } catch(ignore){}
}

logger.info("DESTINATION ENDS ###");

// ---------------------- END block ----------------------

channel.preprocessingScript:
// Modify the message variable below to pre process data
logger.info("[CHANNEL: 1115 TECHBD " + channelName + "]: STEP Preprocessor - START.");

var requestedPath = sourceMap.get('contextPath');

// Read both headers
var overridePath = $('headers').getHeader('X-TechBD-Override-Request-URI');
var requestUri = $('headers').getHeader('X-TechBD-Request-URI');

// Use whichever is present and non-empty (first check override, otherwise requestUri)
var effectivePath = (overridePath && overridePath.trim() !== '')
    ? overridePath.trim()
    : (requestUri && requestUri.trim() !== '')
        ? requestUri.trim()
        : null;

// If we found a usable override path, apply it
if (effectivePath !== null) {
    requestedPath = effectivePath;
}

channelMap.put("requestedPath", requestedPath);
logger.info("[CHANNEL: 1115 TECHBD " + channelName + "]: Preprocessor - contextPath=" + sourceMap.get('contextPath') + ", overridePath=" + overridePath + ", X-TechBD-Request-URI=" + requestUri + ", resolved requestedPath=" + requestedPath);



if (
    requestedPath == "/" ||
    requestedPath == "/healthcheck" ||
    requestedPath == "/tenants"||
    requestedPath == "/tenants/"
) {
    logger.info("[CHANNEL: 1115 TECHBD " + channelName + "]: Preprocessor - requestedPath=" + requestedPath + " needs no body/tenant validation, short-circuit return.");
    return;
}

// ---- REQUEST BODY VALIDATION ----
if (requestedPath != "/tenants" || requestedPath != "/tenants/") {

if (message == null || String(message).trim() === "") {
    var errorMessage = "Validation Error: Required request body is missing";
    logger.error(errorMessage);
    setErrorResponse(400, errorMessage);
    throw errorMessage;
}
logger.info("[CHANNEL: 1115 TECHBD " + channelName + "]: Preprocessor - request body present, length=" + String(message).length);
}
channelMap.put('channelName',channelName);


var incomingInteractionId = $('headers').getHeader('X-TechBD-Interaction-ID');
var incomingCorrelationId = $('headers').getHeader('X-Correlation-ID');

var interactionId;

if (incomingInteractionId != null && incomingInteractionId.trim() !== '') {
    interactionId = incomingInteractionId;
    logger.info("[CHANNEL: 1115 TECHBD " + channelName + "]: Preprocessor - using incoming X-TechBD-Interaction-ID: " + interactionId);
} else if (incomingCorrelationId != null && incomingCorrelationId.trim() !== '') {
    interactionId = incomingCorrelationId;
    logger.info("[CHANNEL: 1115 TECHBD " + channelName + "]: Preprocessor - using incoming X-Correlation-ID as interactionId: " + interactionId);
} else {
    interactionId = generateUuid();
    logger.info("[CHANNEL: 1115 TECHBD " + channelName + "]: Preprocessor - generated new interactionId: " + interactionId);
}


channelMap.put('interactionId', interactionId);

var groupInteractionId = "";
var incomingGroupId = $('headers').getHeader('X-TechBD-Group-Interaction-ID');

if (incomingGroupId != null && incomingGroupId.trim() !== '') {
    groupInteractionId = incomingGroupId.trim();
}

var masterInteractionId = "";
var incomingMasterId = $('headers').getHeader('X-TechBD-Master-Interaction-ID');

if (incomingMasterId != null && incomingMasterId.trim() !== '') {
    masterInteractionId = incomingMasterId.trim();
}

channelMap.put("groupInteractionId", groupInteractionId);
channelMap.put("masterInteractionId", masterInteractionId);
globalMap.put("groupInteractionId", groupInteractionId);
globalMap.put("masterInteractionId", masterInteractionId);


// Get the URI from sourceMap
var uri = sourceMap.get('uri');
var getQueryParameter = globalMap.get('getQueryParam');
//Extract 'source'
var source = getQueryParameter(uri, 'source');

if (!source || source.trim() === '') {
    var headerSource = $('headers').getHeader('X-TechBD-Source-Type');
    if (headerSource && headerSource.trim() !== '') {
        source = headerSource.trim();
    } else {
        source = 'FHIR';
    }
}

// Store back for further use
channelMap.put('source', source);

// ---- Historical Replay Query Parameters ----
// ooSize: full (default) | lite | none
//var ooSizeParam = getQueryParameter(uri, 'ooSize');
//if (ooSizeParam != null) { ooSizeParam = ooSizeParam.trim().toLowerCase(); }
//if (ooSizeParam !== 'lite' && ooSizeParam !== 'none' && ooSizeParam !== 'full') {
//    ooSizeParam = 'full';
//}
//**********************************

var ooSizeParam = getQueryParameter(uri, 'ooSize');

if (ooSizeParam == null || ooSizeParam.trim() === '') {
    ooSizeParam = 'full';
} else {
    ooSizeParam = ooSizeParam.trim().toLowerCase();

    if (ooSizeParam !== 'lite' &&
        ooSizeParam !== 'none' &&
        ooSizeParam !== 'full') {

        setErrorResponse(
            400,
            "Invalid ooSize. Allowed values are: full, lite, none."
        );

        throw "Invalid ooSize parameter";
    }
}

channelMap.put('ooSize', ooSizeParam);

// dataLedger: true (default) | false
var dataLedgerParam = getQueryParameter(uri, 'dataLedger');
if (dataLedgerParam != null) { dataLedgerParam = dataLedgerParam.trim().toLowerCase(); }
if (dataLedgerParam !== 'true' && dataLedgerParam !== 'false') {
    dataLedgerParam = 'true';
}
channelMap.put('dataLedgerParam', dataLedgerParam);

logger.info("Historical Replay params -> ooSize: " + ooSizeParam + ", dataLedger: " + dataLedgerParam);


var tenantId = $('headers').getHeader('X-TechBD-Tenant-ID');
logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: tenantid: " + tenantId);
channelMap.put('tenantId', tenantId);


var userAgent = $('headers').getHeader('User-Agent');
channelMap.put('userAgent', userAgent);




var severity = $('headers').getHeader('X-TechBD-Validation-Severity-Level')
            || $('headers').getHeader('x-techbd-validation-severity-level');

var validationSeverityLevel = "error";
var incomingSeverity = $('headers').getHeader('X-TechBD-Validation-Severity-Level');


// If header has valid value, use it; otherwise keep default
if (incomingSeverity != null && incomingSeverity.trim() !== '') {
    validationSeverityLevel = incomingSeverity;
}

channelMap.put("validationSeverityLevel",validationSeverityLevel);


var igVersion = "";
var incomingIgVersion = $('headers').getHeader('X-SHIN-NY-IG-Version');

if (incomingIgVersion != null && incomingIgVersion.trim() !== '') {
    igVersion = incomingIgVersion;
}

channelMap.put('igVersion', igVersion);

var elaboration = "";
var incomingElaboration = $('headers').getHeader('X-TechBD-Elaboration');

// If header has valid value, use it; otherwise keep default (empty string or any fallback)
if (incomingElaboration != null && incomingElaboration.trim() !== '') {
    elaboration = incomingElaboration.trim();
}

function getValue(value) {
    return (value == null || String(value).trim() === '') ? null : String(value).trim();
}

if (source === 'FHIR') {

    var elaborationObj = {
        headers: {
            "OverrideRequestURI": $('headers').getHeader('X-TechBD-Override-Request-URI'),
            "RequestURI": channelMap.get("requestedPath"),
            "InteractionID": channelMap.get('interactionId'),
            "CorrelationID": $('headers').getHeader('X-Correlation-ID'),
            "GroupInteractionID": getValue(channelMap.get("groupInteractionId")),
            "MasterInteractionID": getValue(channelMap.get("masterInteractionId")),
            "SourceType": $('headers').getHeader('X-TechBD-Source-Type'),
            "TenantID": $('headers').getHeader('X-TechBD-Tenant-ID'),
            "ValidationSeverityLevel": $('headers').getHeader('X-TechBD-Validation-Severity-Level'),
            "SHINNYIGVersion": $('headers').getHeader('X-SHIN-NY-IG-Version')
        }
    };

    elaboration = JSON.stringify(elaborationObj);

}

channelMap.put("elaboration", elaboration);


var healthCheck = "";
var incomingHealthCheck = $('headers').getHeader('X-TechBD-HealthCheck');

if (incomingHealthCheck != null && incomingHealthCheck.trim() !== '') {
    healthCheck = incomingHealthCheck.trim();
}

channelMap.put("healthCheck", healthCheck);
logger.info("**************[FhirBundleHistoricalReplay] incomingHealthCheck raw: " + incomingHealthCheck + " | healthCheck stored: " + healthCheck);


// Check if the header is null or empty
if (tenantId == null || String(tenantId).trim() === "") {
    // Log the error for debugging
    var errorMessage = 'Bad Request: Missing required header X-TechBD-Tenant-ID';
    logger.error("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: " + errorMessage);
    setErrorResponse(400, errorMessage); // Set the HTTP response status to 400 (Bad Request)
    throw errorMessage; // Stop further processing by throwing an exception
}

logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: STEP Preprocessor - END. tenantId validated, proceeding to filter/transformer.");

return message;

channel.postprocessingScript:
var Instant = Packages.java.time.Instant;
var Duration = Packages.java.time.Duration;

var chlName = channelMap.get('channelName');
var interactionId = channelMap.get("interactionId");
var isActionDiscard = channelMap.get("isActionDiscard");
var requestUri = channelMap.get("requestUri");;

logger.info("[CHANNEL: 1115 TECHBD " + chlName + "][INTERACTION ID: " +interactionId +" ]: STEP Postprocessor - START. isActionDiscard=" + isActionDiscard + ", ooSize=" + channelMap.get('ooSize') + ", dataLedgerParam=" + channelMap.get('dataLedgerParam'));

var requestedPath = channelMap.get('requestedPath');
logger.info("requestedPath"+requestedPath);
if (
    requestedPath == "/" ||
    requestedPath == "/healthcheck"
) {
    logger.info("[CHANNEL: 1115 TECHBD " + chlName + "][INTERACTION ID: " +interactionId +" ]: Postprocessor - requestedPath=" + requestedPath + ", nothing further to do, returning.");
    return;
}


if (requestedPath == "/tenants" || requestedPath == "/tenants/") {

    logger.info("[CHANNEL: 1115 TECHBD " + chlName + "][INTERACTION ID: " +interactionId +" ]: Postprocessor - returning /tenants response.");
    var body = String(channelMap.get("tenantResponse"));

    responseMap.put("responseStatusCode", 200);
    responseMap.put("responseContentType", "application/json");
    responseMap.put("finalResponse", body);

    return;
}

logger.info("[CHANNEL: 1115 TECHBD " + chlName + "][INTERACTION ID: " +interactionId +" ]: Postprocessor STARTS.");


// ------------------------------------------------------------------
// Get DataLake Response from channelMap (NOT responseMap anymore)
// ------------------------------------------------------------------

var responseDataLakeStatus = channelMap.get("datalake_status_code");
var responseDataLakeData = channelMap.get("datalake_response_body");
var responseDataLakeStatusText = channelMap.get("datalake_status_text");
var dataLakeErrorMessage = channelMap.get("datalake_response_message");
var destinationDataLakeName = "dest_datalake";

logger.info("DataLake HTTP Status: " + responseDataLakeStatus+" DataLake HTTP Status Text: " + responseDataLakeStatusText+" DataLake Response Body: " + responseDataLakeData);

	// Check if the response exists
if (responseDataLakeStatusText && isActionDiscard != "discard") {



var saveFHIRPayload = globalMap.get('saveFHIRPayload');
var tenantId = $('headers').getHeader('X-TechBD-Tenant-ID');
var source = channelMap.get("source");

var datalakeApiUrl = channelMap.get('DATALAKE_API_URL');



		var status = "";

		try {



		    // Validate DataLake API URL first
		    if (!datalakeApiUrl || datalakeApiUrl.trim() === '') {
		        responseDataLakeData = JSON.stringify({
		            status: "failure",
		            error: "DataLake API URL is empty or missing",
		            message: "DataLake API URL is empty or missing",
		            tenantId: tenantId,
		            rootCause: "Invalid configuration",
		            mostSpecificCause: "Missing DataLake API URL",
		            dataLakeApiBaseURL: datalakeApiUrl
		        });
		    }
		    else if (!/^https?:\/\//i.test(datalakeApiUrl)) {
		        responseDataLakeData = JSON.stringify({
		            status: "failure",
		            error: "Invalid DataLake API URL scheme. Failed to resolve '" + datalakeApiUrl + "'",
		            message: "Failed to resolve '" + datalakeApiUrl + "'",
		            tenantId: tenantId,
		            rootCause: "Invalid URL scheme : DataLake API URL must start with http or https",
		            mostSpecificCause: "Unsupported protocol in DataLake API URL",
		            dataLakeApiBaseURL: datalakeApiUrl
		        });
		    }

			// --------------------------------------------------------------
			// 2 HTTP Error Handling (>=400)
			// --------------------------------------------------------------
			else if (responseDataLakeStatus >= 400) {
				var httpMessage = responseDataLakeStatus + " " + responseDataLakeStatusText + " from POST " + datalakeApiUrl;

			    var finalMessage = httpMessage;

			    // Only for server errors
				if (responseDataLakeStatus >= 500) {

				    // 1 First priority: message already extracted earlier
				    if (dataLakeErrorMessage && String(dataLakeErrorMessage).trim() !== "") {

				        finalMessage = dataLakeErrorMessage;

				    }

				    // 2 Second priority: try parsing API response
				    else if (responseDataLakeData) {

				        try {
				            var errObj = JSON.parse(responseDataLakeData);

				            if (errObj && errObj.message && String(errObj.message).trim() !== "") {
				                finalMessage = errObj.message;
				            }

				        } catch (ignore) {
				            logger.warn("Response not JSON, using HTTP message");
				        }

				    }
				}


				responseDataLakeData = JSON.stringify({
					status: "failure",
					dataLakeApiBaseURL: datalakeApiUrl,
					error: responseDataLakeStatus+" "+responseDataLakeStatusText+" from POST " + datalakeApiUrl,
					message: finalMessage,
					tenantId: tenantId,
					statusCode: responseDataLakeStatus,
					statusText: responseDataLakeStatusText,
					responseBody: responseDataLakeData,
					rootCause: null,
					mostSpecificCause: responseDataLakeStatus+" "+responseDataLakeStatusText+" from POST " + datalakeApiUrl
				});
			}

			 // Parse DataLake response if present
			    if (responseDataLakeData && responseDataLakeData.trim() !== "") {
			        var dlResponse = JSON.parse(responseDataLakeData);
			        status = (dlResponse.status || "").toLowerCase();
			    }



		} catch (e) {

			logger.error("Invalid JSON from DataLake: " + e);

			responseDataLakeData = JSON.stringify({
				status: "failure",
				error: e.toString(),
				message: "Failed to resolve "+datalakeApiUrl,
				tenantId: tenantId,
				statusCode: responseDataLakeStatus,
				statusText: responseDataLakeStatusText,
				responseBody: responseDataLakeData,
				rootCause: "JSON parsing error",
				mostSpecificCause: e.message || e.toString(),
				dataLakeApiBaseURL: datalakeApiUrl
			});

			status = "failure";
		}






		if (status === "success") {

		    var operation = "saveForwardFHIRSuccess";
		logger.info("[CHANNEL: 1115 TECHBD " + chlName + "][INTERACTION ID: " +interactionId +" ]:  saveForwardFHIRSuccess - FHIR Data Lake Complete Payload save ");

		try{
			logger.info("[CHANNEL: 1115 TECHBD " + chlName + "][INTERACTION ID: " +interactionId +" ]: REGISTER State Complete : BEGIN for inteaction id  : "+interactionId + " tenant id : " + tenantId + " requestUri : " + requestUri);
			var start = Instant.now();

		     var operation = "saveForwardFHIRSuccess";
		     var result = saveFHIRPayload(
			   interactionId,
			   tenantId,
			   requestUri,
			   responseDataLakeData ,
			   operation,source
			);
			var end = Instant.now();
			var elapsedMillis = Duration.between(start, end).toMillis();
			logger.info("[CHANNEL: 1115 TECHBD " + chlName + "][INTERACTION ID: " +interactionId +" ]: REGISTER State Complete : END for interaction id: "+interactionId + " tenant id: " + tenantId + ". Time taken: "+ elapsedMillis);
		} catch (e) {
			LOG.error("[CHANNEL: 1115 TECHBD " + chlName + "][INTERACTION ID: " +interactionId +" ]: ERROR:: REGISTER State Complete CALL for interaction id : "+interactionId + " tenant id : " + tenantId );
			var errorMsg;
	            if (e instanceof JavaException) {
	                errorMsg = "ERROR:: REGISTER State Complete CALL for interaction id : "+interactionId + " tenant id : " + tenantId + " :  " + e.toString();
	                throw errorMessage;
	            } else {
	                errorMsg = "Unexpected error during saving: " + e.message;
	                throw errorMessage;
	            }
		}
		} else {
		    logger.info("[CHANNEL: 1115 TECHBD " + chlName + "][INTERACTION ID: " +interactionId +" ]: error - status: " + status);
		    var operation = "saveForwardFHIRFailure";
		logger.info("[CHANNEL: 1115 TECHBD " + chlName + "][INTERACTION ID: " +interactionId +" ]:  saveForwardFHIRFailure - FHIR Data Lake Forward Payload save ");

		try{
			logger.info("[CHANNEL: 1115 TECHBD " + chlName + "][INTERACTION ID: " +interactionId +" ]: REGISTER State Fail : BEGIN for inteaction id  : "+interactionId + " tenant id : " + tenantId);
			var start = Instant.now();


		     var operation = "saveForwardFHIRFailure";
		     var result = saveFHIRPayload(
			   interactionId,
			   tenantId,
			   requestUri,
			   responseDataLakeData ,
			   operation,source
			);
			var end = Instant.now();
			var elapsedMillis = Duration.between(start, end).toMillis();
			logger.info("[CHANNEL: 1115 TECHBD " + chlName + "][INTERACTION ID: " +interactionId +" ]: REGISTER State Fail : END for interaction id: "+interactionId + " tenant id: " + tenantId + ". Time taken: "+ elapsedMillis);
		} catch (e) {
			LOG.error("[CHANNEL: 1115 TECHBD " + chlName + "][INTERACTION ID: " +interactionId +" ]: ERROR:: REGISTER State Fail CALL for interaction id : "+interactionId + " tenant id : " + tenantId );
			var errorMsg;
	            if (e instanceof JavaException) {
	                errorMsg = "ERROR:: REGISTER State Fail CALL for interaction id : "+interactionId + " tenant id : " + tenantId + " :  " + e.toString();
	                throw errorMessage;
	            } else {
	                errorMsg = "Unexpected error during saving: " + e.message;
	                throw errorMessage;
	            }
		}
		}






	} else {
	    logger.info("[CHANNEL: 1115 TECHBD " + chlName + "][INTERACTION ID: " +interactionId +" ]: response found for destination Data Lake: " + destinationDataLakeName);
	}

logger.info("[CHANNEL: 1115 TECHBD " + chlName + "][INTERACTION ID: " +interactionId +" ]: Postprocessor ENDS.");

return;

channel.deployScript:
// This script executes once when the channel is deployed
// You only have access to the globalMap and globalChannelMap here to persist data

var PGobject = Packages.org.postgresql.util.PGobject;

function toJsonb(value) {
    var jsonbObj = new PGobject();
    jsonbObj.setType("jsonb");

	if (typeof value === "object") {
        value = JSON.stringify(value);
    }

    jsonbObj.setValue(value);
    logger.info("jsonbObj: " + jsonbObj);
    return jsonbObj;
}

function saveFHIRPayload(interactionId, tenantId, requestUri, payloadJson, operation,source) {

	logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]:tenantId: " + tenantId);
	logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]:requestUri: " + requestUri);
	logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: operation: " + operation);

	var DriverManager = java.sql.DriverManager;
	var conn = null;
	var stmt = null;
  var groupInteractionId = globalMap.get("groupInteractionId");
  var masterInteractionId = globalMap.get("masterInteractionId");
	logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " + interactionId
        + " ]: groupInteractionId: " + groupInteractionId
        + ", masterInteractionId: " + masterInteractionId);
	try {


	    var jdbcUrl = globalMap.get('jdbcUrl');
		if(jdbcUrl != null) {
		    globalMap.put('jdbcUrl', jdbcUrl);
		} else {
		    var errorMessage = 'MC_JDBC_URL variable is not set';
		    logger.error(errorMessage);
		    setErrorResponse(500, errorMessage); // Set the HTTP response status to 500 (Server error)
		    throw errorMessage; // Stop further processing by throwing an exception
		}

		var jdbcUsername = globalMap.get('JDBC_USERNAME');
		if(jdbcUsername != null) {
		    globalMap.put('jdbcUsername', jdbcUsername);
		} else {
		    var errorMessage = 'MC_JDBC_USERNAME variable is not set';
		    logger.error("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: " +errorMessage);
		    setErrorResponse(500, errorMessage); // Set the HTTP response status to 500 (Server error)
		    throw errorMessage; // Stop further processing by throwing an exception
		}

		var jdbcPassword = globalMap.get('JDBC_PASSWORD');
		if(jdbcPassword != null) {
		    globalMap.put('jdbcPassword', jdbcPassword);

		} else {
		    var errorMessage = 'MC_JDBC_PASSWORD variable is not set';
		    logger.error("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: "  + errorMessage);
		    setErrorResponse(500, errorMessage); // Set the HTTP response status to 500 (Server error)
		    throw errorMessage; // Stop further processing by throwing an exception
		}

	    // Database connection details
		var dbUrl = globalMap.get('jdbcUrl');
		var dbUser = globalMap.get('jdbcUsername');
		var dbPassword = globalMap.get('jdbcPassword');

	    conn = DriverManager.getConnection(dbUrl, dbUser, dbPassword);

	    logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: Database connection established successfully.");

		var sql =
		  "select techbd_udi_ingress.register_interaction_fhir_request(" +
		  "?::text, ?::text, ?::jsonb, ?::jsonb, ?::text, ?::text, ?::jsonb, " +
		  "?::text, ?::text, ?::text, ?::text, ?::text, ?::text, ?::text, ?::text, ?::text, " +
		  "?::timestamptz, ?::text, ?::boolean, ?::text, ?::text, ?::text, ?::text, ?::text, ?::jsonb, ?::text" +
		  ")";

	 // prepareCall(sql) done before
		stmt = conn.prepareCall(sql);

		// 1. p_interaction_id
		stmt.setString(1, interactionId);

		// 2. p_interaction_key  (you stated second is requestUri)
		stmt.setString(2, requestUri);

		// 3. p_nature jsonb -- include tenantId inside nature as you did
		var natureObj;
		if (operation === "saveForwardFHIRPayload") {
		  natureObj = { nature: 'Forward HTTP Request', tenant_id: tenantId };
		} else if (operation === "saveForwardFHIRSuccess") {
		  natureObj = { nature: 'Forwarded HTTP Response', tenant_id: tenantId };
		} else if (operation === "saveForwardFHIRFailure") {
		  natureObj = { nature: 'Forwarded HTTP Response Error', tenant_id: tenantId };
		} else {
		  natureObj = { nature: operation || 'UNKNOWN', tenant_id: tenantId };
		}
		stmt.setObject(3, toJsonb(JSON.stringify(natureObj)), java.sql.Types.OTHER);
		// 4. p_payload jsonb: set payload JSON or NULL for og case
		if (operation === "saveForwardFHIRPayload") {
		   stmt.setObject(4, toJsonb(payloadJson), java.sql.Types.OTHER);
		} else {
		  // if payloadJson is already a JSON string
		  stmt.setObject(4, payloadJson, java.sql.Types.OTHER);
		}

		// 5. p_payload_text text (if you want to store as raw text) — choose either text or null
		stmt.setNull(5, java.sql.Types.VARCHAR);

		// 6. p_rule_namespace text
		stmt.setNull(6, java.sql.Types.VARCHAR);

		// 7. p_elaboration jsonb
		stmt.setNull(7, java.sql.Types.OTHER);

		// 8. p_content_type text
		stmt.setNull(8, java.sql.Types.VARCHAR);

		// 9. p_from_state text  (you were setting these earlier to "DISPOSITION"/"FORWARD", etc.)
		if (operation === "saveForwardFHIRPayload") {
		  stmt.setString(9, "DISPOSITION");
		  stmt.setString(10, "FORWARD");
		} else if (operation === "saveForwardFHIRSuccess") {
		  stmt.setString(9, "FORWARD");
		  stmt.setString(10, "COMPLETE");
		} else if (operation === "saveForwardFHIRFailure") {
		  stmt.setString(9, "FORWARD");
		  stmt.setString(10, "FAIL");
		} else {
		  stmt.setNull(9, java.sql.Types.VARCHAR);
		  stmt.setNull(10, java.sql.Types.VARCHAR);
		}

		// 11. p_state_transition_reason
		stmt.setNull(11, java.sql.Types.VARCHAR);

		// 12. p_user_id
		stmt.setNull(12, java.sql.Types.VARCHAR);

		// 13. p_user_name
		stmt.setNull(13, java.sql.Types.VARCHAR);

		// 14. p_user_session
		stmt.setNull(14, java.sql.Types.VARCHAR);

		// 15. p_user_role
		stmt.setNull(15, java.sql.Types.VARCHAR);

		// 16. p_created_by
		stmt.setNull(16, java.sql.Types.VARCHAR);

		// 17. p_created_at (timestamp with time zone)
		stmt.setNull(17, java.sql.Types.TIMESTAMP_WITH_TIMEZONE);


		var featureEnabled = String(globalMap.get("ORG_TECHBD_PROCESSING_AGENT_FEATURE_ENABLED")).toLowerCase() === "true";
		var configuredTenants = globalMap.get("ORG_TECHBD_PROCESSING_AGENT_TENANT_IDS");
		var configuredAgentValue = globalMap.get("ORG_TECHBD_PROCESSING_AGENT_VALUE");

		var processingAgentFinal = tenantId;

		if (featureEnabled && configuredTenants != null) {
		    var tenantList = String(configuredTenants)
		        .split(",")
		        .map(function(t) { return t.trim().toUpperCase(); });

		    if (tenantId != null && tenantList.indexOf(String(tenantId).toUpperCase()) !== -1) {
		        processingAgentFinal = configuredAgentValue; // TXD
		    }
		}

		var provenanceString =
		    "channel:" + channelName +
		    ", script:deploy";

		// ONLY for Forward HTTP Request
		if (operation === "saveForwardFHIRPayload") {
		    provenanceString += ", processingAgent:" + processingAgentFinal;
		}
		// 18. p_provenance
		stmt.setString(18, provenanceString);

		// 19. p_hub_upsert_behavior boolean
		stmt.setNull(19, java.sql.Types.BOOLEAN);

		// 20. p_source_hub_interaction_id
		stmt.setString(20, masterInteractionId);

		// 21. p_origin
		stmt.setNull(21, java.sql.Types.VARCHAR);

		// 22. p_source_type
		stmt.setString(22, source);

		// 23. p_group_hub_interaction_id
		var normalizedSource = source ? String(source).trim().toUpperCase() : null;
		if (normalizedSource === 'CSV'){
			stmt.setString(23, groupInteractionId);
			}
		else{
		stmt.setNull(23, java.sql.Types.VARCHAR);
		}

		// 24. p_request_source
		stmt.setNull(24, java.sql.Types.VARCHAR);

		// 25. p_additional_details jsonb
			if (operation === "saveForwardFHIRSuccess" || operation === "saveForwardFHIRFailure") {	
			var endTime = java.time.Instant.now();
			var finishIso;
			if (endTime instanceof java.time.Instant) {
			    finishIso = endTime.toString(); // good ISO format e.g. 2025-11-12T14:09:47.637109646Z
			} else if (typeof endTime === 'string') {
			    finishIso = endTime;
			} else {
			    finishIso = (new Date()).toISOString();
			}

		var additionalDetailsObj = {
		  request: {
		    "X-Observability-Metric-Interaction-Finish-Time": finishIso
		  }
		};
		stmt.setObject(25, toJsonb(additionalDetailsObj), java.sql.Types.OTHER);
		} else{
		stmt.setNull(25, java.sql.Types.OTHER);
		}

		// 26. p_techbd_version_number text
		stmt.setNull(26, java.sql.Types.VARCHAR);

		// execute
		var result = stmt.execute();

	} catch (e) {
	    logger.error("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: Error executing stored procedure: " + e);
	} finally {
	    if (stmt != null) stmt.close();
	    if (conn != null) conn.close();
	    logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]:  DB connection closed.");
	}
}

globalMap.put('saveFHIRPayload', saveFHIRPayload);



function sendDataLedgerSync(payload,interactionId) {


    var apiUrl = globalMap.get("DATA_LEDGER_API_URL");
    var dataLedgerApiKey = globalMap.get("TECHBD_NYEC_DATALEDGER_API_KEY");

    if (apiUrl == null) {
        throw new Error("Environment variable DATA_LEDGER_API_URL is not set.");
    }
    if (dataLedgerApiKey == null) {
        throw new Error("Environment variable 'TECHBD_NYEC_DATALEDGER_API_KEY' is not set.");
    }

    try {
        var HttpClients = org.apache.http.impl.client.HttpClients;
        var HttpPost = org.apache.http.client.methods.HttpPost;
        var StringEntity = org.apache.http.entity.StringEntity;
        var EntityUtils = org.apache.http.util.EntityUtils;

        var httpClient = HttpClients.createDefault();
        var httpPost = new HttpPost(apiUrl);

        httpPost.setHeader("Content-Type", "application/json");
        httpPost.setHeader("Accept", "application/json");

        if (dataLedgerApiKey != null) {
        	httpPost.setHeader("x-api-key", dataLedgerApiKey); // Add x-api-key header
        }

        var entity = new StringEntity(payload, "UTF-8");
        httpPost.setEntity(entity);


        try {
        	var response = httpClient.execute(httpPost);
            var statusCode = response.getStatusLine().getStatusCode();
            logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: sendDataLedgerSync response status: " + statusCode);
            var responseBody = EntityUtils.toString(response.getEntity());

            if (statusCode >= 200 && statusCode < 300) {
                logger.info("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: Data Ledger API Response: " + responseBody);
                return {
                    statusCode: statusCode,
                    body: responseBody
                };
            } else {
                logger.error("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: Data Ledger API Error. Status: " + statusCode + ", Response: " + responseBody);
                throw new Error("Request failed with status " + statusCode);
            }
        } finally {
            EntityUtils.consumeQuietly(response.getEntity());
             httpClient.close();
        }
    } catch (error) {
        logger.error("[CHANNEL: 1115 TECHBD " + channelName + "][INTERACTION ID: " +interactionId +" ]: Data Ledger API Request Failed: " + error.message);
        throw error;
    }
}

globalMap.put('sendDataLedgerSync', sendDataLedgerSync);

// Function to extract a query param from the URI
function getQueryParam(uriString, paramName) {
    if (!uriString) return null;
    var regex = new RegExp('[?&]' + paramName + '=([^&]*)', 'i');
    var match = uriString.match(regex);
    return (match && match[1]) ? decodeURIComponent(match[1]) : null;
}
globalMap.put('getQueryParam', getQueryParam);

return;

